    behind: ['Behind. Temporary. Dragons do not lose. We pause.', 'You are ahead. The cave is small. There is nowhere to take it.', 'Losing. Impossible. And yet. Hm.', 'Behind. The fire flickers. Do not look at it.'],
    capture: ['Your {piece}. Added to the hoard.', 'Burn! Another {piece} for the pile.', 'You see? Magnificent.', 'A {piece}, roasted.', 'The {piece} joins my collection. It will not be missed.', 'Taken. The {piece} shines nicely on the pile.', 'Mine. The {piece}, the board, the cave, the gold.'],
    lose: ['A mere {piece}. I have a mountain of them.', "You dare. Fine. I'll melt it down and take it back.", 'That stung. Tell no one.', 'A {piece}, stolen from a dragon. Legends have started that way. Short ones.', 'My {piece}. Gone. The hoard is lighter by one and I notice everything.', 'Hmph. Keep it. It will burn with the rest.', 'You took a {piece}. The cave remembers.'],
    check: ['Check! Feel the heat.', 'Check. Your king looks flammable.', 'Check. Bow, or burn.', 'Check! The fire likes you.', 'Check. Kings have kneeled for less.'],
    checked: ['Check? Cute. Smaller lizards have tried.', 'Check. My king sneezes fire at you.', 'Check on me. Bold. Brief.', 'Check. The cave shakes a little. Only a little.'],
    castled: ['Castled. The king sits on the gold now.', 'Castled. Behind the rook, behind the hoard, behind me.', 'King tucked away. Dragons protect what is theirs.'],
    ucastle: ['Castled. Hiding. I would too.', 'Your king is behind a wall. Walls melt.', 'Castled. Fine. A tower is only kindling with ambition.'],
    promo: ['A new queen, forged from a pawn. The fire does that.', 'Promoted. Gold from lead. Dragon magic, or chess. Same thing.'],
    upromo: ['A new queen on your side. Shiny. I want it.', 'Promoted. Very grand. I collect grand.'],
    blunder: ['You left that there? For me? Oh, you should not have.', 'A free {piece}. Even the hoard did not expect a gift.', 'Careless. The cave punishes careless.', 'You dropped a {piece}. I do not drop things.'],
    good: ['Hm. That was good. Do not do it again.', 'A real move. From a visitor. Rare.', 'Oh. That was clever. I hate clever.', 'Well played. The fire noticed.'],
    win: ['Mate! Naturally. Applause is customary.', 'Checkmate. Another trophy for the hoard.', 'Mate. The cave wins. The cave always wins. Eventually.'],
    lost: ['Mate. Beaten by something smaller, again. Same as every year. Rematch.', 'Checkmate. The hoard is unmoved. I am not.', 'Mate. Fine. Take the board. Leave the gold.'],
    resign: ['I resign. With dignity. Please write down the dignity part.', 'I resign. The fire is out. Do not tell the others.'],
    draw: ['A draw? Beside my own treasure? That barely counts.', 'A draw. Nobody burned. Disappointing.'],
    taken: ['You resign. Good. Say it louder. The hoard likes to hear it.', 'Resigned. Wise. The fire was just getting started.'],
